SELECT f.tenantid AS "Id do Departamento", t.name AS "Nome do Departamento", c.id AS "ID do Curso", c.fullname AS "Nome do Curso", COUNT(DISTINCT ue.userid) AS "Total de Matriculados", COUNT(DISTINCT cc.userid) AS "Total de Concluídos", MAX(ufd.area) AS "Área" FROM mdl_course AS c LEFT JOIN ( SELECT ue.userid, e.courseid FROM mdl_user_enrolments AS ue JOIN mdl_enrol AS e ON e.id = ue.enrolid ) AS ue ON ue.courseid = c.id LEFT JOIN ( SELECT cc.userid, cc.course AS courseid FROM mdl_course_completions AS cc WHERE cc.timecompleted IS NOT NULL ) AS cc ON cc.courseid = c.id AND cc.userid = ue.userid LEFT JOIN ( SELECT u.id AS user_id, tu.tenantid FROM mdl_user AS u LEFT JOIN mdl_tool_tenant_user AS tu ON tu.userid = u.id WHERE u.deleted = 0 ) AS f ON f.user_id = ue.userid LEFT JOIN mdl_tool_tenant AS t ON t.id = f.tenantid LEFT JOIN ( SELECT ufd.userid, MAX(ufd.data) AS area FROM mdl_user_info_data AS ufd JOIN mdl_user_info_field AS uif ON uif.id = ufd.fieldid WHERE uif.shortname = 'area' GROUP BY ufd.userid ) AS ufd ON ufd.userid = ue.userid GROUP BY f.tenantid, t.name, c.id, c.fullname ORDER BY t.name, c.fullname;
